<script setup lang="ts">defineProps<{frozen:number|null;current:number|null;stale:boolean;label?:string}>();function rev(x:number|null|undefined){return x===null||x===undefined?'未记录旧版':String(x)}</script><template><span class="revision-badge" :class="stale?'stale':'fresh'" :title="label||'研究冻结的底稿版本与当前版本'"><b>底稿 v{{rev(frozen)}}</b><span>当前 v{{rev(current)}}</span><em>{{stale?'已过期':'与当前一致'}}</em></span></template>
